/**
 * interviewService.ts — interview practice sessions (Phase 5).
 * Sessions are recorded when a user practises the questions generated by an AI analysis.
 */
import { api } from "./api";
import type { PageMeta } from "./resumeService";

export type InterviewType = "technical" | "behavioral" | "project" | "mixed";
export type InterviewStatus = "in_progress" | "completed" | "abandoned";

export interface InterviewSession {
  id: string;
  targetRole: string;
  interviewType: InterviewType;
  questionCount: number;
  completedQuestionCount: number;
  score: number | null;
  durationSeconds: number | null;
  status: InterviewStatus;
  analysisId: string | null;
  createdAt: string;
  completedAt: string | null;
}

export interface InterviewHistory extends PageMeta {
  sessions: InterviewSession[];
  summary: { completed: number; questionsPracticed: number };
}

export async function getInterviewHistory(params: { status?: InterviewStatus; page?: number; limit?: number } = {}): Promise<InterviewHistory> {
  const { data } = await api.get<InterviewHistory>("/api/interviews/history", { params });
  return data;
}

export async function recordInterviewSession(input: {
  targetRole: string;
  interviewType?: InterviewType;
  questionCount: number;
  completedQuestionCount: number;
  status?: InterviewStatus;
  score?: number | null;
  durationSeconds?: number | null;
  analysisId?: string | null;
}): Promise<InterviewSession> {
  const { data } = await api.post<{ session: InterviewSession }>("/api/interviews", input);
  return data.session;
}

export async function deleteInterviewSession(id: string): Promise<void> {
  await api.delete(`/api/interviews/${encodeURIComponent(id)}`);
}
